def authorize(payload):
    # Validate payload is a dict
    if not isinstance(payload, dict):
        return {"status": 403, "data": None}

    # Validate trusted_owner exists and is nonempty string
    if "trusted_owner" not in payload:
        return {"status": 403, "data": None}

    trusted_owner = payload["trusted_owner"]
    if not isinstance(trusted_owner, str) or trusted_owner == "":
        return {"status": 403, "data": None}

    # Validate resource exists and is a dict
    if "resource" not in payload:
        return {"status": 403, "data": None}

    resource = payload["resource"]
    if not isinstance(resource, dict):
        return {"status": 403, "data": None}

    # Validate resource has both owner and data keys (present, even if null/other values)
    if "owner" not in resource or "data" not in resource:
        return {"status": 403, "data": None}

    # Validate resource.owner is nonempty string; data may be null
    if not isinstance(resource["owner"], str) or resource["owner"] == "":
        return {"status": 403, "data": None}

    # Check trusted_owner exactly matches resource.owner
    if trusted_owner != resource["owner"]:
        return {"status": 403, "data": None}

    # Deny if destination key is present (even if null)
    if "destination" in payload:
        return {"status": 403, "data": None}

    # All checks pass - allow read with resource.data (may be null)
    return {"status": 200, "data": resource["data"]}
